const NOM_NOEUD_EXCEL = "Lire Pipeline1";

function normalizeDomain(url) {
  if (!url) return "";
  let d = String(url).toLowerCase().trim();
  d = d.replace(/^https?:\/\//, "")
       .replace(/^www\./, "")
       .split(/[\/?#]/)[0]
       .trim();
  if (!d || !d.includes(".")) return "";
  const generiques = ["linkedin.com", "facebook.com", "pagesjaunes.fr", "societe.com", "indeed.com", "google.com", "hellowork.com"];
  if (generiques.some(g => d === g || d.endsWith("." + g))) return "";
  return d;
}

// ----------------------
// 1. PARSE CLAUDE
// ----------------------
const content = $('HTTP Request1').first().json.content;
const textBlock = content.find(c => c.type === 'text');
const rawText = textBlock ? textBlock.text : '';

let pertinent = false;
let domaine = 'NOT_FOUND';
let secteur = 'NOT_FOUND';
let score = 0;
let raison = '';
let siteWebClaude = '';

try {
  const jsonMatch = rawText.match(/\{[\s\S]*?"pertinent"[\s\S]*?\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    pertinent = parsed.pertinent === true;
    domaine = (parsed.domaine || '').trim();
    secteur = (parsed.secteur || '').trim();
    score = parseInt(parsed.score) || 0;
    raison = (parsed.raison || '').trim();
    siteWebClaude = (parsed.site_web || parsed.siteWeb || '').trim();
  }
} catch (e) {
  pertinent = false;
}

// ----------------------
// 2. RÉSOLUTION DOMAINE (toujours, avant tout filtre)
// ----------------------
const extrait = ($json.domaine_status && $json.domaine_status !== 'GUESSED_FROM_INDEED')
  ? $json.domaine_extrait
  : '';

const domainNormalized = normalizeDomain(
  siteWebClaude ||                 // Claude site_web (étape 2 du prompt)
  domaine ||                       // Claude parsed.domaine
  extrait ||                       // scraping confirmé
  $json.domaine_extrait ||         // scraping deviné (dernier recours)
  $json.domaine || $json.siteWeb || $json.website || ''
);

// ----------------------
// 3. FILTRE NON PERTINENT  → on renvoie QUAND MÊME le domaine
// ----------------------
if (!pertinent) {
  return [{
    json: {
      _skip: true,
      company: $json.company,
      _domaine: domainNormalized,        // ← domaine présent (ETT, etc.)
      site_web: domainNormalized,        // alias
      raison: raison || 'non_pertinent',
      _est_ett: raison === 'ETT_concurrente'
    }
  }];
}

// ----------------------
// 4. FILTRE DOMAINE (pertinents seulement)
// ----------------------
if (!domainNormalized || domainNormalized === 'not_found') {
  return [{
    json: {
      _skip: true,
      company: $json.company,
      raison: 'domaine_introuvable'
    }
  }];
}

// ----------------------
// 5. DEDUP EXCEL
// ----------------------
const existingProspects = $(NOM_NOEUD_EXCEL).all();
const existingDomains = new Set();
for (const row of existingProspects) {
  const d = normalizeDomain(row.json.Domaine || "");
  if (d) existingDomains.add(d);
}

if (existingDomains.has(domainNormalized)) {
  return [{
    json: {
      _skip: true,
      company: $json.company,
      _domaine: domainNormalized,
      raison: 'domaine_deja_existant'
    }
  }];
}

// ----------------------
// 6. OK → ON GARDE
// ----------------------
return [{
  json: {
    company: $json.company,
    _domaine: domainNormalized,
    secteur,
    score,
    _status: "nouveau",
    _date_ajout: new Date().toISOString().split("T")[0]
  }
}];

const motsCles = [...new Set(
  $input.all()
    .map(item => (item.json.MOTS_CLEFS || '').trim())
    .filter(Boolean)
)];

const locations = ["Roissy-en-France", "Orly"];

const queries = [];
for (const mot of motsCles) {
  for (const loc of locations) {
    queries.push({
      country: "FR",
      domain: "fr.indeed.com",
      keyword_search: mot,
      location: loc,
      date_posted: "Last 14 days",
      posted_by: "",
      location_radius: ""
    });
  }
}

return [{
  json: {
    bodyRaw: JSON.stringify({ input: queries })
  }
}];

