        pertinent: false,
        raison: 'site_web_deja_existant',
        classification: 'OUT',
        score: 0
      };
      break;
    }
  }
}

// --- Décision finale ---
const domaineValide = /^([a-z0-9](-*[a-z0-9])*\.)+[a-z]{2,}$/i.test(siteItem);

return [{
  json: {
    ...original,
    ...result,
