function normalizeCompany(name) {
  if (!name) return "";
  return name
    .toLowerCase()
    .replace(/\s+(sas|sarl|sa|sasu|eurl|sci|scop|eti|group|groupe)\b/g, "")
    .replace(/[^a-z0-9àâäéèêëïîôùûüÿçœæ]/g, "")
    .trim();
}

// --- Lecture défensive des sources de dédup ---
// Plusieurs noms de colonne possibles selon la feuille (Entreprise / Company / Nom)
function readCompanies(nodeName, colonnes) {
  const out = [];
  let rows = [];
  try {
    rows = $(nodeName).all();
  } catch (e) {
    console.log(`⚠️ Node "${nodeName}" non exécuté ou introuvable — ignoré`);
    return out;
  }
  for (const row of rows) {
    let val = '';
    for (const col of colonnes) {
      if (row.json[col]) { val = row.json[col]; break; }
    }
    const norm = normalizeCompany(val);
    if (norm) out.push(norm);
  }
  return out;
}

const COLS = ['Entreprise', 'Company', 'entreprise', 'company', 'Nom'];

const srcPipeline    = readCompanies('Lire Pipeline1',   COLS);
const srcRejete      = readCompanies('Lire rejeté2',     COLS);
const srcConcurrents = readCompanies('Lire Concurrents', COLS);

const existingCompanies = new Set([...srcPipeline, ...srcRejete, ...srcConcurrents]);

console.log(`Dédup : pipeline=${srcPipeline.length} rejetés=${srcRejete.length} concurrents=${srcConcurrents.length} → ${existingCompanies.size} uniques`);

// --- Matching ---
// Garde-fou : le match par sous-chaîne ne s'applique qu'aux noms assez longs.
// Sans ça, une entrée courte type "ram" ou "af" rejette tout ce qui la contient
// ("bramtech", "safran"...). Risque décuplé maintenant qu'on charge ~293 concurrents.
const MIN_SUBSTR = 6;

function isExisting(normName) {
  if (!normName) return false;
  if (existingCompanies.has(normName)) return normName;
  if (normName.length < MIN_SUBSTR) return false;
  for (const existing of existingCompanies) {
    if (existing.length < MIN_SUBSTR) continue;
    if (normName.includes(existing) || existing.includes(normName)) return existing;
  }
  return false;
}

// --- Traitement des offres ---
const allOffres = $input.all();
if (!allOffres.length) {
  return [{ json: { _info: "aucun item en entrée" } }];
}

const seenIds = new Set();
const seenEntreprises = new Set();
const results = [];
let skipDoublon = 0, skipExistant = 0;

for (const o of allOffres) {
  // Dédup par jobid
  const offreId = o.json.jobid || '';
  if (offreId) {
    if (seenIds.has(offreId)) { skipDoublon++; continue; }
    seenIds.add(offreId);
  }

  // Dédup par entreprise (intra-run)
  const nom = o.json.company_name || '';
  const norm = normalizeCompany(nom);
  if (!norm) continue;
  if (seenEntreprises.has(norm)) { skipDoublon++; continue; }
  seenEntreprises.add(norm);

  // Dédup contre Pipeline / Rejetés / Concurrents
  const match = isExisting(norm);
  if (match) {
    console.log(`⛔ "${nom}" → déjà connu (match: "${match}")`);
    skipExistant++;
    continue;
  }

  results.push({
    json: {
      company_name: nom,
      entreprise: nom,
      id: o.json.jobid || '',
      intitule: o.json.job_title || '',
      typeContrat: o.json.job_type || '',
      lieu: o.json.job_location || o.json.location || '',
      salaire: o.json.salary_formatted || '',
      description: o.json.description_text || '',
      description_text: o.json.description_text || '',
      job_description_formatted: o.json.job_description_formatted || '',
      company_link: o.json.company_link || '',
      dateCreation: o.json.date_posted_parsed || '',
      urlOffre: o.json.url || '',
      source: 'Indeed',
      _date_check: new Date().toISOString().split('T')[0]
    }
  });
}

console.log(`Résultat : ${results.length} nouvelles / ${allOffres.length} offres (${skipDoublon} doublons, ${skipExistant} déjà connues)`);

if (!results.length) {
  return [{ json: { _info: "aucune nouvelle entreprise trouvée" } }];
}
return results;

